import {dateKey} from "../date.js";
import {icon} from "./icons.js";

function frame(title, body, extraClass = "") {
  return `<dialog class="app-dialog ${extraClass}" aria-labelledby="dialog-title"><div class="dialog-heading"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close-dialog" aria-label="Fermer la fenêtre">${icon("close")}</button></div>${body}</dialog>`;
}
export function jumpDialog(state) {
  return frame("Aller à une date", `<p class="dialog-description">Retrouve une date passée ou prépare les jours à venir.</p><form id="jump-form"><label class="field-label" for="jump-date">Date</label><input type="date" id="jump-date" name="date" min="0001-01-01" max="9999-12-31" value="${dateKey(state.date)}" required/><div class="dialog-actions"><button class="text-button" type="button" data-action="jump-today">Aller à aujourd’hui</button><button class="primary-button" type="submit">Voir cette date ${icon("arrowRight")}</button></div></form>`, "jump-dialog");
}
export function preferencesDialog(state) {
  return frame("Préférences", `<p class="dialog-description">Quelques réglages pour un calendrier à ton goût.</p><form id="preferences-form"><div class="setting-row"><div><label for="week-start">Début de la semaine</label><p>Pour le calendrier et son aperçu dans le menu.</p></div><select id="week-start" name="weekStart"><option value="1" ${state.preferences.weekStart === 1 ? "selected" : ""}>Lundi</option><option value="0" ${state.preferences.weekStart === 0 ? "selected" : ""}>Dimanche</option></select></div><div class="setting-row"><div><label for="time-format">Format de l’heure</label><p>Affichage des heures dans les vues semaine et jour.</p></div><select id="time-format" name="timeFormat"><option value="12" ${state.preferences.timeFormat === "12" ? "selected" : ""}>12 heures</option><option value="24" ${state.preferences.timeFormat === "24" ? "selected" : ""}>24 heures</option></select></div><div class="setting-row"><div><label for="search-engine">Moteur de recherche</label><p>Pour la barre de recherche de l’accueil.</p></div><select id="search-engine" name="searchEngine"><option value="google" ${state.preferences.searchEngine !== "duckduckgo" ? "selected" : ""}>Google</option><option value="duckduckgo" ${state.preferences.searchEngine === "duckduckgo" ? "selected" : ""}>DuckDuckGo</option></select></div><div class="setting-row timezone-setting"><div><span class="setting-title">Fuseau horaire</span><p>Amérique / Toronto</p></div><span class="setting-zone">Heure de l’Est</span></div><div class="preferences-note">${icon("check")} Tes préférences sont enregistrées sur cet appareil.</div><div class="dialog-actions"><button class="primary-button" type="submit">Enregistrer</button></div></form>`, "preferences-dialog");
}
export function shortcutsDialog() {
  const shortcuts = [["Recherche Web", "/"], ["Nouvel événement", "N"], ["Accueil", "H"], ["Vue mois", "M"], ["Vue semaine", "W"], ["Vue jour", "D"], ["Aller à aujourd’hui", "T"], ["Aller à une date", "G"], ["Période précédente / suivante", "←", "→"], ["Afficher les raccourcis", "?"], ["Fermer la fenêtre", "Échap"]];
  return frame("Raccourcis clavier", `<p class="dialog-description">Quelques touches pour naviguer plus vite.</p><div class="shortcut-list">${shortcuts.map(([label, ...keys]) => `<div><span>${label}</span><span>${keys.map(key => `<kbd>${key}</kbd>`).join(" ")}</span></div>`).join("")}</div><p class="shortcut-note">Dans la vue mois, utilise les flèches pour changer de date. Appuie sur Entrée pour ouvrir la semaine, puis clique sur un jour pour voir son horaire. Le fil d’Ariane permet de revenir en arrière.</p>`);
}
